import contextlib

class RefDebugQuit(Exception):  # noqa: N818
    pass


def refdebug(obj, top_level=True, exclude=()):
    from types import FrameType

    def is_excluded(o):
        for ex in exclude:
            if o is ex:
                return True

        from sys import _getframe
        return bool(isinstance(o, FrameType)
                    and o.f_code.co_filename == _getframe().f_code.co_filename)

    if top_level:
        with contextlib.suppress(RefDebugQuit):
            refdebug(obj, top_level=False, exclude=exclude)
        return

    import gc
    print_head = True
    print("-------------->")
    try:
        reflist = [x for x in gc.get_referrers(obj)
                if not is_excluded(x)]

        idx = 0
        while True:
            if print_head:
                print("referring to", id(obj), type(obj), obj)
                print("----------------------")
                print_head = False
            r = reflist[idx]

            s = str(r.f_code) if isinstance(r, FrameType) else str(r)

            print(f"{idx}/{len(reflist)}: ", id(r), type(r), s)

            if isinstance(r, dict):
                for k, v in r.items():
                    if v is obj:
                        print("...referred to from key", k)

            print("[d]ig, [n]ext, [p]rev, [e]val, [r]eturn, [q]uit?")

            response = input()

            if response == "d":
                refdebug(r, top_level=False, exclude=exclude+tuple(reflist))
                print_head = True
            elif response == "n":
                if idx + 1 < len(reflist):
                    idx += 1
            elif response == "p":
                if idx - 1 >= 0:
                    idx -= 1
            elif response == "e":
                print("type expression, obj is your object:")
                expr_str = input()
                try:
                    res = eval(expr_str, {"obj": r})  # pylint:disable=eval-used
                except Exception:  # pylint:disable=broad-except
                    from traceback import print_exc
                    print_exc()
                print(res)
            elif response == "r":
                return
            elif response == "q":
                raise RefDebugQuit
            else:
                print("WHAT YOU SAY!!! (invalid choice)")

    finally:
        print("<--------------")

